    (HERE / 'FRONT.md').write_text(front)
    lines = ['# All active runs and their limits of evidence', '', "PASS applies to the specified digital/source bound gate . Calibrated means only explicitly specified source context; no new physical calibration was performed. All calculation measures and times are PHENOMENOLOGICAL . The original measurement/model support is available per row and in CURATED_DEMOS.json . Original delivery review and this execution is separate; the package's older PENDING/NOT_READY is not changed by a new numerical PASS.", '', '| Kommando efter startskriptet | Verb and Objects | Limited result | Knowledge Status / resolution | Ursprunglig leveransgrind | Recycle / Mismatch | Tid s / scope-kvitto |', '|---|---|---|---|---|---|---|']
    for r in rows:
        ident = r['demo_id']
        rec = runs.get(ident)
        status = rec['status'] if rec else 'PENDING'
        mismatch = str(rec['mismatch_count']) if rec and rec['mismatch_count'] is not None else 'UNKNOWN'
        wall = f"{rec['wall_seconds']:.3f}" if rec else '—'
        failure = ' (RESOURCE_LIMIT)' if rec and rec.get('failure_kind') == 'RESOURCE_LIMIT' else ''
        lines.append(f"| `{ident}` | {r['label']} | {r['reader_result']} | {r['knowledge_status']}; {r['resolution']} | {r['delivery_review_status']} | {status}{failure}; {mismatch} | {wall}; [exactly runcope](raw/receipts/{ident}.json) |")
    (HERE / 'ALL_DEMOS.md').write_text('\n'.join(lines) + '\n')
    counts = {'PRESENT': 7, 'PARTIAL': 39, 'REFUTED': 2, 'RESEARCH': 3, 'MISSING': 1}
    proposal = {'counts_current': counts, 'counts_proposed': counts, 'new_status_changes': 0, 'K16': 'MISSING', 'new_PRESENT': 0, 'new_reviews': delta, 'evidence_delta': ['Regional height response under explicit closure', 'Measured-state/static load consumer requiring same-person Newton port', 'Regional edit with freeze-integrity repair', 'Whole anatomy and spatial contact negative 72-design result', 'Three source-bound protocol facets'], 'review_state': 'PENDING_INDEPENDENT_REVIEW', 'source_spec_sha256': sha(PACKAGE.parent.parent / 'notes/NORTHSTAR_SPEC.md')}
